contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint v, bool preInitialize) public {
        bool reverted;

        // optionally initialize first
        if (preInitialize) {
            c.Initialized();
        }

        // read MinSum before the deciding call
        uint beforeMinSum = c.MinSum();

        // deciding call: SetMinSum(v)
        try c.SetMinSum(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read MinSum after the deciding call
        uint afterMinSum = c.MinSum();

        // general rule:
        //   if preInitialize is true, Initialized() has been called, so SetMinSum must revert
        //   and MinSum must remain unchanged.
        //   if preInitialize is false, SetMinSum must succeed and MinSum must equal v.
        assert(
            preInitialize
                ? (reverted && afterMinSum == beforeMinSum)
                : (!reverted && afterMinSum == v)
        );
    }

    receive() external payable {}
}

