contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime) public payable {
        require(lockTime > 0, "Put with positive lockTime should not revert");
        require(msg.value > 0, "Put with value should not revert");

        // Ensure Initialized has not been called so Put is not blocked by reentrancy or initialization checks.
        // SetMinSum and SetLogFile are intentionally not called; Put only needs LogFile to be non-null to not revert.
        // However, LogFile is a contract type; a zero address would cause an external call to fail and revert Put.
        // The test assumes c was deployed with a valid LogFile address, as required for Put to be usable.
        // If LogFile is zero, Put will revert; the rule below is conditional on lockTime > 0 and would then be false,
        // but the checker deploys a fresh P where Put is expected to be usable. We drive Put directly.

        uint balanceBefore = address(c).balance;
        uint unlockBefore = c.Acc(address(this)).unlockTime();

        bool reverted;
        try c.Put{value: msg.value}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted);
        assert(c.Acc(address(this)).balance() >= msg.value);
        assert(c.Acc(address(this)).unlockTime() >= block.timestamp + lockTime);
        assert(address(c).balance >= balanceBefore + msg.value);
    }

    receive() external payable {}
}

