contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount, uint minSum) public payable {
        require(address(this).balance >= putAmount);

        // setup: configure MinSum and init (order matters for this contract)
        c.SetMinSum(minSum);
        c.Initialized();

        // record balance before committing funds
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));

        // drive c via its public payable Put entry to establish a holder record
        c.Put{value: putAmount}(lockTime);

        (uint unlockAfter, uint balAfter) = c.Acc(address(this));

        // ensure lock time has passed so the time gate is satisfiable in some execution path
        // (block.timestamp is not controllable, so we cannot force it; we only assert invariants
        //  that hold regardless of whether the Collect branch is entered or revert occurs)

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockFinal, uint balFinal) = c.Acc(address(this));

        // General rule: after any Collect, the caller's recorded balance never increases,
        // and can only decrease by at most the amount requested. This bounds the payout
        // (and catches overpayment or unauthorized balance increases).
        assert(balFinal <= balAfter);
        assert(balAfter - balFinal <= collectAmount);
    }

    receive() external payable {}
}

